  var RESIZE_LISTENER_BOUND_FLAG = "__galgame_overlay_resize_listener_bound__";
  function setupGameContentResizeListener() {
    if (topWindow[RESIZE_LISTENER_BOUND_FLAG]) {
      console.log(`[${SCRIPT_NAME}] 窗口 resize 监听已存在，跳过重复注册`);
      return;
    }
    topWindow[RESIZE_LISTENER_BOUND_FLAG] = true;
    let resizeTimer = null;
    let isProcessing = false;
    const handleResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        if (isProcessing) return;
        isProcessing = true;
        const $overlay = $2(topWindow.document).find("#gal-global-overlay");
        if ($overlay.hasClass("active")) {
          if ($overlay.hasClass("fullscreen")) {
            resetGameContentScale();
          } else {
            adjustGameContentScale();
          }
          adjustToolbarForSpace();
          resizePixiEffects();
        }
        requestAnimationFrame(() => {
          isProcessing = false;
        });
      }, 200);
    };
    topWindow.addEventListener("resize", handleResize);
    setTimeout(() => {
      const $overlay = $2(topWindow.document).find("#gal-global-overlay");
      if ($overlay.hasClass("fullscreen")) {
        resetGameContentScale();
      } else {
        adjustGameContentScale();
      }
      adjustToolbarForSpace();
      resizePixiEffects();
    }, 800);
  }

