  function syncHistoryModalSkinClass($modal) {
    if (!$modal?.length) return;
    const $overlay = $2("#gal-global-overlay");
    [...SHUJIAN_FAMILY_SKIN_IDS, ...PERSONA_FAMILY_SKIN_IDS, ...ANCIENT_FAMILY_SKIN_IDS, ...JRPG_FAMILY_SKIN_IDS, ...YANYUN_FAMILY_SKIN_IDS, DEFAULT_DARK_SKIN_ID].forEach((skinClass) => {
      $modal.toggleClass(skinClass, $overlay.hasClass(skinClass));
    });
  }
  function getHistoryFromDatabase() {
    try {
      const api2 = topWindow.AutoCardUpdaterAPI;
      if (!api2 || typeof api2.exportTableAsJson !== "function") {
        console.log(`[${SCRIPT_NAME}] AutoCardUpdaterAPI 不可用`);
        return [];
      }
      const tableData = api2.exportTableAsJson();
      if (!tableData) return [];
      let summarySheet = null;
      for (const sheetKey of Object.keys(tableData)) {
        if (!sheetKey.startsWith("sheet_")) continue;
        const sheet = tableData[sheetKey];
        if (sheet.name === "总结表") {
          summarySheet = sheet;
          break;
        }
      }
      if (!summarySheet || !summarySheet.content || summarySheet.content.length < 2) {
        console.log(`[${SCRIPT_NAME}] 未找到总结表或表为空`);
        return [];
      }
      const headers = summarySheet.content[0];
      const content = summarySheet.content;
      let indexCol = -1;
      let timeCol = -1;
      let contentCol = -1;
      const indexKeywords = ["索引", "编码", "index", "id", "序号", "编号"];
      const timeKeywords = ["时间", "跨度", "日期", "time", "date", "duration"];
      const contentKeywords = ["纪要", "总结", "内容", "文本", "summary", "content", "text", "剧情", "故事"];
      headers.forEach((header, idx) => {
        if (!header) return;
        const h2 = String(header).toLowerCase().trim();
        if (indexCol === -1 && indexKeywords.some((k2) => h2 === k2 || h2.includes(k2))) indexCol = idx;
        if (timeCol === -1 && timeKeywords.some((k2) => h2 === k2 || h2.includes(k2))) timeCol = idx;
        if (contentCol === -1 && contentKeywords.some((k2) => h2 === k2 || h2.includes(k2))) contentCol = idx;
      });
      if (contentCol === -1) {
        console.log(`[${SCRIPT_NAME}] 未能通过表头识别内容列，尝试分析数据内容...`);
        let maxAvgLength = 0;
        let bestCol = -1;
        for (let colIdx = 0; colIdx < headers.length; colIdx++) {
          if (colIdx === indexCol) continue;
          let totalLen = 0;
          let count = 0;
          for (let rowIdx = 1; rowIdx < Math.min(content.length, 6); rowIdx++) {
            const cell = content[rowIdx][colIdx];
            if (cell && typeof cell === "string") {
              totalLen += cell.length;
              count++;
            }
          }
          const avgLen = count > 0 ? totalLen / count : 0;
          if (avgLen > maxAvgLength) {
            maxAvgLength = avgLen;
            bestCol = colIdx;
          }
        }
        if (bestCol !== -1) {
          contentCol = bestCol;
          console.log(`[${SCRIPT_NAME}] 自动推断内容列为索引: ${contentCol} (平均长度: ${maxAvgLength})`);
        }
      }
      if (contentCol === -1) {
        if (headers.length >= 2) {
          contentCol = 1;
          if (indexCol === 1) contentCol = 0;
        } else {
          contentCol = 0;
        }
      }
      if (indexCol === -1 && contentCol !== 0) indexCol = 0;
      if (timeCol === -1 && headers.length >= 3 && contentCol >= 1 && contentCol !== indexCol) {
        timeCol = contentCol - 1;
        if (timeCol === indexCol) timeCol = -1;
      }
      const history = [];
      for (let i2 = 1; i2 < content.length; i2++) {
        const row = content[i2];
        if (!row) continue;
        const text = row[contentCol];
        const idx = indexCol !== -1 ? row[indexCol] : "";
        const time2 = timeCol !== -1 ? row[timeCol] : "";
        if (text) {
          history.push({ index: idx, time: time2, content: text });
        }
      }
      return history;
    } catch (e2) {
      console.error(`[${SCRIPT_NAME}] 获取历史记录失败:`, e2);
      return [];
    }
  }
