      if (action === "delete") {
        if (!window.confirm(`确定删除模型「${target.name}」吗？`)) return;
        const next = models.filter((item) => item.id !== id2);
        void saveModels(next).then(() => showToast2(`已删除模型：${target.name}`));
      }
