  var HTML_SKIN_STYLE_ID = "galgame-html-skin-style";
  function applyHtmlSkinRuntime(skinId) {
    const doc = topWindow.document;
    const record = getCachedHtmlSkin(skinId);
    const oldStyle = doc.getElementById(HTML_SKIN_STYLE_ID);
    if (!record?.scopedCss) {
      if (oldStyle) oldStyle.remove();
      if (record) {
        console.warn(`[${SCRIPT_NAME}] HTML 皮肤 ${record.id} 的样式内容为空，请重新导入该皮肤`);
      }
      return false;
    }
    if (oldStyle?.getAttribute("data-skin-id") === record.id) return true;
    if (oldStyle) oldStyle.remove();
    const style3 = doc.createElement("style");
    style3.id = HTML_SKIN_STYLE_ID;
    style3.setAttribute("data-skin-id", record.id);
    style3.textContent = record.scopedCss;
    doc.head.appendChild(style3);
    console.log(`[${SCRIPT_NAME}] 已应用 HTML 皮肤: ${record.name} (${record.id})`);
    return true;
  }
  function clearHtmlSkinRuntime() {
    const style3 = topWindow.document.getElementById(HTML_SKIN_STYLE_ID);
    if (style3) style3.remove();
  }

