      _$(this).addClass("active").css({ color: THEME.accent, borderBottom: `2px solid ${THEME.accent}` });
      $modal.find(".gal-settings-panel").hide();
      $modal.find(`.gal-settings-panel[data-panel="${tab}"]`).show();
