  var DEFAULT_SPRITE_ASPECT_RATIO = 2 / 3;
  var DEFAULT_SPRITE_UPLOAD_RATIO_LABEL = "2:3";
  var CROPPER_MIN_SCALE = 0.01;
  var CROPPER_HIT_POINT_RADIUS = 9;
