  // src/map/auto-pregen.js
  var PREGEN_BOUND_FLAG = "__galgame_map_pregen_bound__";
  var HARVEST_DEBOUNCE_MS = 3e3;
  var BIND_RETRY_INTERVAL_MS = 5e3;
  var BIND_MAX_RETRIES = 12;
  var harvestTimer = null;
  var isHarvesting = false;
  function isMapEnabled() {
    try {
      return !!getMapSettings().mapSystemEnabled;
    } catch {
      return true;
    }
  }
  async function harvestOnce() {
    if (isHarvesting || !isMapEnabled()) return;
    isHarvesting = true;
    try {
      const harvested = await harvestWorkbenchLayouts();
      if (harvested.length) {
        showToast2(`已为「${harvested.join("」「")}」绘制地图`);
      }
    } catch (e2) {
      console.error(`[${SCRIPT_NAME}] 地图工作台收割失败:`, e2);
    } finally {
      isHarvesting = false;
    }
  }
  function onTableUpdate() {
    if (harvestTimer) topWindow.clearTimeout(harvestTimer);
    harvestTimer = topWindow.setTimeout(() => {
      harvestTimer = null;
      harvestOnce();
    }, HARVEST_DEBOUNCE_MS);
  }
  function tryBind() {
    const api2 = topWindow?.AutoCardUpdaterAPI;
    if (!api2 || typeof api2.registerTableUpdateCallback !== "function") return false;
    api2.registerTableUpdateCallback(onTableUpdate);
    console.log(`[${SCRIPT_NAME}] 地图收割器已挂接数据库表格更新回调`);
    if (isMapEnabled()) {
      ensureSheetsRegistered().catch((e2) => {
        console.warn(`[${SCRIPT_NAME}] 地图双表注册失败（将在填表回调时重试）:`, e2);
      });
    }
    return true;
  }
  function setupMapAutoPregen() {
    if (topWindow[PREGEN_BOUND_FLAG]) {
      console.log(`[${SCRIPT_NAME}] 地图收割器已存在，跳过重复注册`);
      return;
    }
    topWindow[PREGEN_BOUND_FLAG] = true;
    if (tryBind()) return;
    let retries = 0;
    const timer = topWindow.setInterval(() => {
      retries++;
      if (tryBind()) {
        topWindow.clearInterval(timer);
        return;
      }
      if (retries >= BIND_MAX_RETRIES) {
        topWindow.clearInterval(timer);
        topWindow[PREGEN_BOUND_FLAG] = false;
        console.warn(`[${SCRIPT_NAME}] 数据库插件回调接口未就绪，填表生成地图未启用（打开地图仍会即时生成）`);
      }
    }, BIND_RETRY_INTERVAL_MS);
  }

  // src/init.js
